import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"大司命","description":"","frontmatter":{"title":"大司命","date":"2026-11-24T00:00:00.000Z","seq":6,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"屈原","source_book":"楚辞","prev":{"text":"湘夫人","link":"/blogs/楚辞/湘夫人.html"},"next":{"text":"少司命","link":"/blogs/楚辞/少司命.html"}},"headers":[],"relativePath":"blogs/楚辞/大司命.md","filePath":"blogs/楚辞/大司命.md"}'),o={name:"blogs/楚辞/大司命.md"};function l(n,a,c,m,r,_){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="大司命" tabindex="-1">大司命 <a class="header-anchor" href="#大司命" aria-label="Permalink to &quot;大司命&quot;">​</a></h1><p class="poem-meta">先秦 · 屈原　·　九歌</p><div class="poem"><p class="poem-stanza">广开兮天门，纷吾乘兮玄云</p><p class="poem-stanza">令飘风兮先驱，使涷雨兮洒尘</p><p class="poem-stanza">君回翔兮以下，逾空桑兮从女</p><p class="poem-stanza">纷总总兮九州，何寿夭兮在予</p><p class="poem-stanza">高飞兮安翔，乘清气兮御阴阳</p><p class="poem-stanza">吾与君兮齐速，导帝之兮九坑</p><p class="poem-stanza">灵衣兮被被，玉佩兮陆离</p><p class="poem-stanza">一阴兮一阳，众莫知兮余所为</p><p class="poem-stanza">折疏麻兮瑶华，将以遗兮离居</p><p class="poem-stanza">老冉冉兮既极，不寖近兮愈疏</p><p class="poem-stanza">乘龙兮辚辚，高驰兮冲天</p><p class="poem-stanza">结桂枝兮延伫，羌愈思兮愁人</p><p class="poem-stanza">愁人兮奈何，愿若今兮无亏</p><p class="poem-stanza">固人命兮有当，孰离合兮何为？</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
